const $=selector=>document.querySelector(selector);
const locale=window.JIGZI18N?.locale()||"th-TH";
const money=new Intl.NumberFormat(locale,{style:"currency",currency:"THB",maximumFractionDigits:2});
const state={user:null,salesAgent:null,mySales:null,settings:null,products:[],orders:[],users:[],staff:[],ownerRequests:[],accessRequests:[],agents:[],commissions:[],promotions:[],rewards:[],walletRequests:[],creditAccounts:[],creditTransactions:[],closings:[],closingPreview:null,posCart:[],reports:null,health:null,lastChatId:0,chatTimer:null,sound:{enabled:true,volume:1,data:"",name:"เสียงมาตรฐาน JIGᶻ"},knownNewOrders:null,orderMonitorTimer:null,audioContext:null};
addEventListener("DOMContentLoaded",()=>document.querySelector('#orderStatus option[value="NEW"]')?.insertAdjacentHTML("afterend",'<option value="ACCEPTED">รับงานแล้ว</option>'));
addEventListener("DOMContentLoaded",()=>api("/api/settings/public").then(({settings})=>{state.settings=settings;document.body.dataset.theme=settings.theme||"space";if($("#posShipping")&&!$("#posShipping").dataset.edited)$("#posShipping").value=settings.shipping_fee||"0";updatePosTotals()}).catch(()=>{}));
addEventListener("DOMContentLoaded",()=>$("#setTheme").addEventListener("change",event=>{document.body.dataset.theme=event.target.value}));
const labels={NEW:"ออเดอร์ใหม่ / รอรับงาน",ACCEPTED:"รับงานแล้ว",PENDING_PAYMENT:"รอตรวจสอบการชำระเงิน",PAID:"ชำระเงินแล้ว",PACKING:"กำลังแพ็กสินค้า",PACKED:"ตรวจแพ็กเรียบร้อย",SHIPPED:"จัดส่งแล้ว",COMPLETED:"เสร็จสิ้นออเดอร์",CANCELLED:"ยกเลิกออเดอร์"};

function esc(value){return String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char]))}
function date(value){if(!value)return"—";return new Date(String(value).replace(" ","T")+(/Z|[+-]\d\d/.test(value)?"":"Z")).toLocaleString(locale)}
function status(value){return`<b class="status-${esc(value)}">${esc(labels[value]||value)}</b>`}
function toast(message){const element=$("#toast");element.textContent=message;element.classList.add("show");setTimeout(()=>element.classList.remove("show"),2200)}
function modal(title,content){$("#modalTitle").textContent=title;$("#modalBody").innerHTML=content;$("#modal").classList.remove("hidden")}
function closeModal(){$("#modal").classList.add("hidden")}
function labelResponsiveTables(){document.querySelectorAll("table").forEach(table=>{const labels=[...table.querySelectorAll("thead th")].map(cell=>cell.textContent.trim());table.querySelectorAll("tbody tr").forEach(row=>[...row.children].forEach((cell,index)=>{if(cell.tagName==="TD"&&!cell.hasAttribute("colspan"))cell.dataset.label=labels[index]||"ข้อมูล"}))})}
addEventListener("DOMContentLoaded",()=>{labelResponsiveTables();new MutationObserver(labelResponsiveTables).observe(document.body,{childList:true,subtree:true})});
async function api(path,options={}){const method=String(options.method||"GET").toUpperCase(),attempts=method==="GET"?2:1;for(let attempt=0;attempt<attempts;attempt++){try{const signal=options.signal||AbortSignal.timeout(method==="GET"?3500:12000),response=await fetch(path,{...options,signal,headers:{"content-type":"application/json",...(options.headers||{})}});let body={};try{body=await response.json()}catch{}if(response.ok)return body;if(attempt+1<attempts&&response.status>=500){await new Promise(resolve=>setTimeout(resolve,350));continue}throw new Error(body.error||`request_failed_${response.status}`)}catch(error){if(attempt+1>=attempts)throw error;await new Promise(resolve=>setTimeout(resolve,350))}}throw new Error("request_failed")}
function errorText(error){const value=error?.message||"request_failed";if(value.startsWith("insufficient_stock"))return`สต็อกไม่พอ: ${value.split(":")[1]||"สินค้า"}`;if(value.startsWith("request_failed"))return"เชื่อมต่อระบบไม่สำเร็จ กรุณารอสักครู่แล้วกดรีเฟรช";return({invalid_customer:"กรอกข้อมูลลูกค้าให้ครบ",empty_cart:"ยังไม่มีสินค้า",invalid_transition:"สถานะนี้ยังทำรายการดังกล่าวไม่ได้",tracking_required:"กรอกบริษัทขนส่งและเลขพัสดุ",no_subscription:"ยังไม่ได้เปิดแจ้งเตือน",service_unavailable:"ระบบฐานข้อมูลไม่พร้อม",invalid_date_range:"ช่วงวันที่ไม่ถูกต้อง กรุณาเลือกวันที่เริ่มต้นก่อนวันที่สิ้นสุด",invalid_payment:"วิธีชำระเงินไม่ถูกต้อง",invalid_source:"ช่องทางขายไม่ถูกต้อง",owner_required:"รายการนี้ทำได้เฉพาะ OWNER",sales_permission_denied:"บัญชีเซลล์ไม่มีสิทธิ์เปิดเมนูนี้",order_not_found:"ไม่พบออเดอร์นี้",order_delete_requires_closed:"ลบได้เฉพาะออเดอร์ที่สำเร็จหรือยกเลิกแล้ว",primary_owner_required:"รายการนี้ต้องยืนยันโดย OWNER หลัก",secondary_owner_limit:"แต่งตั้ง OWNER รองครบสูงสุด 4 คนแล้ว",primary_owner_protected:"OWNER หลักไม่สามารถถูกลบได้",owner_protected:"ไม่สามารถเปลี่ยนสิทธิ์ OWNER ด้วยวิธีนี้",owner_request_not_found:"ไม่พบคำขอลบ OWNER",owner_request_processed:"คำขอนี้ถูกดำเนินการแล้ว",owner_request_target_changed:"สิทธิ์ของผู้ใช้เปลี่ยนไป กรุณาตรวจสอบใหม่",invalid_owner_decision:"ผลการตรวจคำขอไม่ถูกต้อง",user_not_found:"ไม่พบผู้ใช้",user_balance_not_zero:"ลบไม่ได้: ผู้ใช้ยังมีเครดิตคงเหลือ กรุณาจัดการยอดให้เป็นศูนย์ก่อน",user_wallet_pending:"ลบไม่ได้: ผู้ใช้ยังมีคำขอฝากหรือถอนที่รอตรวจ",linked_user_not_found:"ไม่พบ User ID ที่ต้องการเชื่อม",user_already_agent:"User ID นี้เชื่อมกับตัวแทนรายอื่นแล้ว",wallet_request_not_found:"ไม่พบคำขอฝาก–ถอน",wallet_request_processed:"คำขอนี้ถูกดำเนินการแล้ว",invalid_wallet_status:"สถานะคำขอไม่ถูกต้อง",invalid_credit_account:"กรอกชื่อผู้เครดิต User ID ยอดเครดิต และรหัสให้ถูกต้อง",credit_user_exists:"ผู้ใช้นี้มีรหัสเครดิตที่เปิดใช้งานอยู่แล้ว",credit_code_exists:"รหัสเครดิตนี้ถูกใช้งานแล้ว กรุณาเปลี่ยนรหัส",credit_account_not_found:"ไม่พบบัญชีเครดิต",credit_limit_below_used:"วงเงินใหม่ต้องไม่น้อยกว่ายอดที่ใช้ไปแล้ว",credit_balance_used:"ยังมียอดเครดิตที่ใช้ไป จึงไม่สามารถลบบัญชีได้",product_not_found:"ไม่พบสินค้า",invalid_price_tier_form:"กรุณากรอกจำนวนและราคาให้ครบ ห้ามใช้จำนวนซ้ำ",invalid_sale_price:"ราคาขายเฉพาะบิลต้องมากกว่า 0 บาท",invalid_shipping_fee:"ค่าส่งไม่ถูกต้อง",invalid_cod_amount:"ยอดเก็บปลายทางต้องไม่น้อยกว่ายอดสุทธิ",agent_not_found:"ไม่พบตัวแทน",commission_not_found:"ไม่พบรายการค่าคอม",commission_paid_locked:"ค่าคอมนี้จ่ายเข้ากระเป๋าแล้ว จึงแก้หรือลบไม่ได้",promotion_not_found:"ไม่พบโปรโมชั่น",invalid_commission:"ข้อมูลค่าคอมไม่ถูกต้อง หรือกรุณาใช้ปุ่มจ่ายค่าคอม",invalid_audio:"รองรับไฟล์เสียง MP3, WAV, OGG และ M4A เท่านั้น",audio_too_large:"ไฟล์เสียงต้องมีขนาดไม่เกิน 900 KB",cod_payment_required:"ต้องยืนยันว่าได้รับยอด COD ก่อนปิดออเดอร์",invalid_cod_state:"ยืนยันยอด COD ได้หลังจัดส่งออเดอร์ COD เท่านั้น",invalid_closing_period:"กรุณาเลือกวันหรือเดือนที่ต้องการปิดยอด",invalid_actual_cash:"จำนวนเงินสดนับจริงไม่ถูกต้อง",closing_exists:"รอบนี้ถูกปิดยอดแล้ว ไม่สามารถปิดซ้ำได้",invalid_image:"รองรับไฟล์ JPG, PNG และ WebP เท่านั้น",too_many_images:"ใส่รูปสินค้าได้สูงสุด 5 รูป",image_too_large:"รูปมีขนาดใหญ่เกินไป กรุณาเลือกรูปใหม่",payload_too_large:"ข้อมูลไฟล์รวมมีขนาดใหญ่เกินไป"})[value]||value}

async function weeklyStockCount(){try{const result=await api("/api/admin/stock-counts"),done=result.counts.find(item=>item.week_key===result.weekKey);modal(`ตรวจนับสต๊อก ${result.weekKey}`,`${done?`<p class="notice">สัปดาห์นี้นับแล้วโดย ${esc(done.counted_by_name||done.counted_by)}</p>`:""}<form id="stockCountForm" class="form"><div class="stock-count-list">${result.products.map(product=>`<label><span><b>${esc(product.name)}</b><small>ระบบ ${Number(product.stock)} ${esc(product.unit)}</small></span><input class="field" type="number" min="0" step="0.001" value="${Number(product.stock)}" data-count-product="${esc(product.id)}"></label>`).join("")}</div><textarea id="stockCountNote" class="field" placeholder="หมายเหตุการตรวจนับ"></textarea><button class="button" type="submit" ${done?"disabled":""}>${done?"นับสัปดาห์นี้แล้ว":"ยืนยันยอดจริงและปรับสต๊อก"}</button></form><h3>ประวัติล่าสุด</h3>${result.counts.map(item=>`<div class="summary-row"><b>${esc(item.week_key)}</b><span>${Number(item.item_count)} รายการ · ต่าง ${Number(item.total_variance)}</span><small>${esc(item.counted_by_name||item.counted_by)}</small></div>`).join("")||'<p class="muted">ยังไม่มีประวัติ</p>'}`);const form=$("#stockCountForm");if(!done)form.onsubmit=async event=>{event.preventDefault();try{const items=[...form.querySelectorAll("[data-count-product]")].map(input=>({productId:input.dataset.countProduct,countedQty:input.value}));await api("/api/admin/stock-counts",{method:"POST",body:JSON.stringify({weekKey:result.weekKey,note:$("#stockCountNote").value,items})});toast("บันทึกการนับและปรับสต๊อกแล้ว");closeModal();await loadProducts()}catch(error){toast(errorText(error))}}}catch(error){toast(errorText(error))}}
async function loadRewards(){try{state.rewards=(await api("/api/admin/rewards")).rewards;$("#rewardCards").innerHTML=state.rewards.length?state.rewards.map(item=>`<article class="work-card"><div class="reward-admin-row">${item.image?`<img src="${esc(item.image)}" alt="">`:""}<div><h3>${esc(item.title)}</h3><p>${Number(item.points_cost)} แต้ม · คงเหลือ ${Number(item.stock)} · แลกแล้ว ${Number(item.redeemed_count||0)} · ${esc(item.status)}</p></div></div><footer><button class="button ghost" data-reward-edit="${item.id}">แก้ไข</button><button class="button ghost owner-only ${state.user?.role==="OWNER"?"":"hidden"}" data-reward-delete="${item.id}">ลบ</button></footer></article>`).join(""):'<p class="muted">ยังไม่มีของรางวัล</p>'}catch(error){toast(errorText(error))}}
function editReward(id){const item=state.rewards.find(row=>Number(row.id)===Number(id));if(!item)return;modal("แก้ไขของรางวัล",`<form id="editRewardForm" class="form"><input id="editRewardTitle" class="field" value="${esc(item.title)}" required><textarea id="editRewardDescription" class="field">${esc(item.description||"")}</textarea><input id="editRewardPoints" class="field" type="number" min="1" value="${Number(item.points_cost)}" required><input id="editRewardStock" class="field" type="number" min="0" value="${Number(item.stock)}" required><select id="editRewardStatus" class="field"><option value="ACTIVE" ${item.status==="ACTIVE"?"selected":""}>เปิดให้แลก</option><option value="INACTIVE" ${item.status==="INACTIVE"?"selected":""}>ปิด</option></select><input id="editRewardImage" type="file" accept="image/*"><button class="button" type="submit">บันทึก</button></form>`);$("#editRewardForm").onsubmit=async event=>{event.preventDefault();try{const file=$("#editRewardImage").files[0],image=file?await productImageData(file):item.image||"";await api(`/api/admin/rewards/${id}`,{method:"POST",body:JSON.stringify({title:$("#editRewardTitle").value,description:$("#editRewardDescription").value,pointsCost:$("#editRewardPoints").value,stock:$("#editRewardStock").value,status:$("#editRewardStatus").value,image})});closeModal();await loadRewards();toast("แก้ไขรางวัลแล้ว")}catch(error){toast(errorText(error))}}}
async function deleteReward(id){if(!confirm("ลบของรางวัลนี้? หากมีประวัติแลก ระบบจะปิดใช้งานแทน"))return;try{await api(`/api/admin/rewards/${id}`,{method:"DELETE",body:"{}"});await loadRewards();toast("จัดการรางวัลแล้ว")}catch(error){toast(errorText(error))}}
function showView(id){togglePosCart(false);document.querySelectorAll(".page").forEach(page=>page.classList.toggle("active",page.id===id));document.querySelectorAll("#nav [data-view]").forEach(button=>button.classList.toggle("active",button.dataset.view===id));$("#app").classList.remove("menu-open");loadView(id);scrollTo(0,0)}
async function loadView(id){if(id==="dashboard")await loadDashboard();if(id==="my-sales")await loadMySales();if(["orders","payments","shipping"].includes(id))await loadOrders();if(["products","pos"].includes(id))await loadProducts();if(id==="customers")await loadUsers();if(id==="staff")await loadStaff();if(id==="agents")await loadAgents();if(id==="promotions")await loadPromotions();if(id==="rewards")await loadRewards();if(id==="wallet")await loadWalletRequests();if(id==="closings")await loadClosings();if(["finance","reports"].includes(id))await loadReports();if(id==="health")await loadSystemHealth();if(id==="settings"){await loadSettings();await loadExtendedSettings()}if(id==="chat")await loadChat()}
async function loadExtendedSettings(){const v=(await api("/api/admin/settings")).settings,map={setHeroEyebrow:"hero_eyebrow",setHeroTitle:"hero_title",setHeroDescription:"hero_description",setCatalogTitle:"catalog_title",setFooterText:"footer_text",setMinimumOrder:"minimum_order",setLowStock:"low_stock_threshold",setTransfer:"enable_transfer",setCod:"enable_cod",setCash:"enable_cash",setCredit:"enable_credit",setAccent:"accent_color",setMotion:"motion_enabled",setSupportPhone:"support_phone",setReservationMinutes:"reservation_minutes",setComplianceEnabled:"compliance_enabled",setComplianceTitle:"compliance_title",setComplianceText:"compliance_text",setApprovalThreshold:"dual_approval_threshold",setSalesMaxDiscount:"sales_max_discount_percent",setSalesMinMargin:"sales_min_margin_percent"};for(const[id,key]of Object.entries(map)){const node=document.getElementById(id);if(node)node.value=v[key]??""}}

async function loadDashboard(){try{const [{summary},orders]=await Promise.all([api("/api/admin/summary"),api("/api/admin/orders")]);$("#mOrders").textContent=summary.orders;$("#mTodayOrders").textContent=`วันนี้ ${summary.todayOrders} ออเดอร์`;$("#mPending").textContent=summary.pending;$("#mPacking").textContent=summary.packing;$("#mShipping").textContent=summary.shipping;$("#mLow").textContent=summary.lowStock;$("#mSales").textContent=money.format(summary.todaySales);$("#mOnline").textContent=summary.onlineUsers;$("#mAgents").textContent=summary.activeAgents;$("#mCommission").textContent=money.format(summary.pendingCommission);$("#orderPill").textContent=summary.orders;$("#paymentPill").textContent=summary.pending;$("#shippingPill").textContent=summary.shipping;state.orders=orders.orders;$("#latestOrders").innerHTML=state.orders.slice(0,7).map(order=>`<div class="order-mini"><div><b>${esc(order.id)}</b><small>${esc(order.customer_name)} · ${status(order.status)}</small></div><b>${money.format(order.total)}</b><button class="button small" data-order-detail="${esc(order.id)}">เปิด</button></div>`).join("")}catch(error){toast(errorText(error))}}
async function loadMySales(){try{const result=await api("/api/admin/sales/me");state.mySales=result;if(!result.agent){$("#mySalesIdentity").innerHTML='<p class="notice">บัญชีนี้ยังไม่ได้เชื่อมเป็นเซลล์ กรุณาให้ OWNER เชื่อม User ID กับตัวแทนประเภท SALES</p>';$("#mySalesRows").innerHTML='<tr><td colspan="8">ยังไม่มีข้อมูลเซลล์</td></tr>';return}$("#mySalesIdentity").innerHTML=`<div><span>เซลล์ที่เข้าสู่ระบบ</span><h2>${esc(result.agent.name)}</h2><small>User ID ผูกอัตโนมัติ · ไม่ต้องกรอกรหัสใน POS</small></div><div><span>รหัสเซลล์</span><b>${esc(result.agent.code)}</b></div><div><span>อัตราค่าคอม</span><b>${Number(result.agent.commission_rate).toFixed(2)}%</b></div>`;$("#mySalesOrders").textContent=result.summary.orders;$("#mySalesToday").textContent=money.format(result.summary.todaySales);$("#mySalesMonth").textContent=money.format(result.summary.monthSales);$("#mySalesPending").textContent=money.format(result.summary.pendingCommission);$("#mySalesPaid").textContent=money.format(result.summary.paidCommission);$("#mySalesRows").innerHTML=result.orders.length?result.orders.map(order=>`<tr><td><b>${esc(order.id)}</b></td><td>${esc(order.customer_name)}</td><td>${money.format(order.total)}</td><td>${money.format(order.actual_cost)}</td><td>${money.format(order.profit_base)}</td><td><b>${money.format(order.commission_amount)}</b><small class="muted">${Number(order.commission_rate).toFixed(2)}%</small></td><td>${esc(order.commission_status||"ยังไม่คำนวณ")}</td><td>${date(order.created_at)}</td></tr>`).join(""):'<tr><td colspan="8">ยังไม่มีบิลที่คีย์ด้วยบัญชีนี้</td></tr>'}catch(error){toast(errorText(error))}}
function printMySalesStatement(){const data=state.mySales;if(!data?.agent)return toast("ยังไม่มีข้อมูลเซลล์");const rows=data.orders.map(order=>`<tr><td>${esc(order.id)}</td><td>${date(order.created_at)}</td><td>${money.format(order.total)}</td><td>${money.format(order.actual_cost)}</td><td>${money.format(order.profit_base)}</td><td>${money.format(order.commission_amount)}</td><td>${esc(order.commission_status||"—")}</td></tr>`).join("");modal("ใบสรุปค่าคอม",`<section class="commission-statement receipt"><h2>JIGᶻ AGENT · COMMISSION STATEMENT</h2><p>เซลล์ ${esc(data.agent.name)} · ${esc(data.agent.code)} · อัตรา ${Number(data.agent.commission_rate).toFixed(2)}%</p><p>ออกเอกสาร ${date(new Date().toISOString())}</p><div class="summary-grid"><div><small>ยอดเดือนนี้</small><b>${money.format(data.summary.monthSales)}</b></div><div><small>รอจ่าย</small><b>${money.format(data.summary.pendingCommission)}</b></div><div><small>จ่ายแล้ว</small><b>${money.format(data.summary.paidCommission)}</b></div></div><table><thead><tr><th>ออเดอร์</th><th>วันที่</th><th>ยอดขาย</th><th>ทุน</th><th>กำไร</th><th>ค่าคอม</th><th>สถานะ</th></tr></thead><tbody>${rows||'<tr><td colspan="7">ยังไม่มีรายการ</td></tr>'}</tbody></table><p class="muted">คำนวณจากราคาขายจริงหลังหักต้นทุน FIFO และส่วนหักของบิล</p></section><p><button class="button" onclick="window.print()">พิมพ์ / บันทึก PDF</button></p>`)}

async function loadOrders(){try{const query=new URLSearchParams(),filters={q:$("#orderSearch")?.value.trim(),from:$("#orderFrom")?.value,to:$("#orderTo")?.value,status:$("#orderStatus")?.value,payment:$("#orderPayment")?.value,source:$("#orderSource")?.value};for(const[key,value]of Object.entries(filters))if(value)query.set(key,value);const result=await api(`/api/admin/orders?${query}`);state.orders=result.orders;const summary=$("#orderFilterSummary");if(summary)summary.textContent=`พบ ${state.orders.length} รายการ${filters.from||filters.to?` · วันที่ ${filters.from||"เริ่มต้น"} ถึง ${filters.to||"ปัจจุบัน"}`:""}`;renderOrders();renderPayments();renderShipping()}catch(error){toast(errorText(error))}}
function actions(order){let main={NEW:["ACCEPTED","รับงาน"],ACCEPTED:["PACKING","เริ่มแพ็ก"],PENDING_PAYMENT:["PAID","ยืนยันเงิน"],PAID:["PACKING","เริ่มแพ็ก"],PACKING:["PACKED","ตรวจแพ็กแล้ว"],PACKED:["SHIP","จัดส่ง"]}[order.status];if(order.status==="SHIPPED")main=order.payment_method==="COD"&&!order.cod_received_at?["COD_RECEIVED","ยืนยันยอด COD"]:["COMPLETED","ปิดออเดอร์"];let html=`<button data-order-detail="${esc(order.id)}">ดู</button>`;if(main)html+=`<button data-order-action="${main[0]}" data-order-id="${esc(order.id)}">${main[1]}</button>`;if(["PACKING","PACKED"].includes(order.status))html+=`<button class="button ghost" data-order-rollback="${esc(order.id)}" data-order-status="${esc(order.status)}" data-order-payment="${esc(order.payment_method)}">ย้อนสถานะแพ็ก</button>`;if(!["SHIPPED","COMPLETED","CANCELLED"].includes(order.status))html+=`<button data-order-action="CANCELLED" data-order-id="${esc(order.id)}">ยกเลิก</button>`;if(state.user?.role==="OWNER"&&["COMPLETED","CANCELLED"].includes(order.status))html+=`<button class="order-delete-button" data-order-delete="${esc(order.id)}">ลบ</button>`;return html}
function renderOrders(){const body=$("#orderRows");if(!body)return;body.innerHTML=state.orders.length?state.orders.map(order=>`<tr><td><b>${esc(order.id)}</b></td><td>${esc(order.customer_name)}<small class="muted">${esc(order.phone||"")}</small></td><td>${esc(order.source)}</td><td>${esc(order.payment_method)}</td><td><b>${money.format(order.total)}</b></td><td>${status(order.status)}</td><td>${date(order.created_at)}</td><td><div class="row-actions">${actions(order)}</div></td></tr>`).join(""):`<tr><td colspan="8">ยังไม่มีออเดอร์</td></tr>`}
function renderPayments(){const root=$("#paymentCards");if(!root)return;const rows=state.orders.filter(order=>order.status==="PENDING_PAYMENT");root.innerHTML=rows.length?rows.map(order=>`<article class="work-card"><h3>${esc(order.id)}</h3><p>${esc(order.customer_name)} · ${esc(order.phone)}</p><div class="total">${money.format(order.total)}</div><p>${date(order.created_at)}</p><footer><button class="button ghost" data-order-detail="${esc(order.id)}">ดูสลิป</button><button class="button orange" data-order-action="PAID" data-order-id="${esc(order.id)}">ยืนยันยอด</button></footer></article>`).join(""):`<article class="work-card"><h3>ไม่มีรายการรอตรวจ</h3><p>ออเดอร์ที่รอชำระเงินจะแสดงที่นี่</p></article>`}
function renderShipping(){const root=$("#shippingCards");if(!root)return;const rows=state.orders.filter(order=>order.status==="PACKED"||(order.status==="SHIPPED"&&order.payment_method==="COD"&&!order.cod_received_at));root.innerHTML=rows.length?rows.map(order=>{const awaitingCod=order.status==="SHIPPED";return`<article class="work-card"><h3>${esc(order.id)}</h3><p>${esc(order.customer_name)}<br>${esc(order.address||"")}</p><div class="total">${money.format(order.total)}</div>${awaitingCod?`<p class="status-PENDING_PAYMENT">รอยืนยันยอด COD${order.customer_received_at?" · ลูกค้ารับแล้ว":""}</p>`:""}<footer><button class="button ghost" data-order-detail="${esc(order.id)}">รายละเอียด</button><button class="button" data-order-action="${awaitingCod?"COD_RECEIVED":"SHIP"}" data-order-id="${esc(order.id)}">${awaitingCod?"ยืนยันยอด COD":"ใส่เลขพัสดุ"}</button></footer></article>`}).join(""):`<article class="work-card"><h3>ไม่มีรายการพร้อมส่ง</h3><p>ออเดอร์ที่ตรวจแพ็กแล้วหรือรอตรวจยอด COD จะแสดงที่นี่</p></article>`}
async function orderDetail(id){try{const order=(await api(`/api/admin/orders/${encodeURIComponent(id)}`)).order;const proof=order.payment_proof?`<h3>หลักฐานการชำระเงิน</h3><img src="${esc(order.payment_proof)}" alt="Payment proof" style="max-width:100%;max-height:420px;border-radius:12px">`:"",cod=order.payment_method==="COD"?`<p class="notice"><b>COD</b><br>ลูกค้ายืนยันรับ: ${order.customer_received_at?date(order.customer_received_at):"ยังไม่ยืนยัน"}<br>แอดมินยืนยันยอด: ${order.cod_received_at?date(order.cod_received_at):"ยังไม่ได้รับยอด"}</p>`:"",credit=order.payment_method==="CREDIT"?`<p class="notice success"><b>เครดิตร้าน</b><br>ผู้เครดิต: ${esc(order.creditor_name||"OWNER")}<br>หักยอดเครดิตแล้ว ${money.format(order.total)}</p>`:"";modal(`ออเดอร์ ${order.id}`,`<div class="modal-grid"><div><p><b>ลูกค้า</b><br>${esc(order.customer_name)} · ${esc(order.phone)}<br>${esc(order.address)}</p><p><b>ชำระเงิน</b> ${esc(order.payment_method)}<br><b>สถานะ</b> ${status(order.status)}</p></div><div><p><b>ยอดสินค้า</b> ${money.format(order.subtotal)}<br><b>ส่วนลด</b> ${money.format(order.discount)}<br><b>ค่าส่ง</b> ${money.format(order.shipping_fee)}<br><b>รวม</b> ${money.format(order.total)}</p><p><b>ขนส่ง</b> ${esc(order.tracking_company||"—")} ${esc(order.tracking_number||"")}</p></div></div>${cod}${credit}<div class="table-wrap"><table><thead><tr><th>สินค้า</th><th>จำนวน</th><th>ราคา/หน่วย</th><th>รวม</th></tr></thead><tbody>${order.items.map(item=>`<tr><td>${esc(item.product_name)}</td><td>${item.quantity} ${esc(item.unit)}</td><td>${money.format(item.unit_price)}</td><td>${money.format(item.line_total)}</td></tr>`).join("")}</tbody></table></div>${proof}<p><button class="button ghost" onclick="window.print()">พิมพ์/บันทึกบิล</button></p>`)}catch(error){toast(errorText(error))}}
async function deleteOrder(id){const order=state.orders.find(item=>item.id===id);if(state.user?.role!=="OWNER")return toast("รายการนี้ทำได้เฉพาะ OWNER");if(order&&!['COMPLETED','CANCELLED'].includes(order.status))return toast("ลบได้เฉพาะออเดอร์ที่สำเร็จหรือยกเลิกแล้ว");const reason=prompt(`เหตุผลที่ลบออเดอร์ ${id}\nระบบจะคืนสต็อกและบันทึกชื่อผู้ลบ`,"ลบออกจากหน้าทำงาน");if(reason===null)return;if(!confirm(`ยืนยันลบออเดอร์ ${id} และคืนจำนวนสินค้า?`))return;try{const result=await api(`/api/admin/orders/${encodeURIComponent(id)}`,{method:"DELETE",body:JSON.stringify({reason})});toast(`ลบโดย ${result.deletedBy} · คืนสต็อก ${Number(result.returnedQuantity||0)} หน่วย`);closeModal();await Promise.all([loadOrders(),loadProducts(),loadDashboard()])}catch(error){toast(errorText(error))}}
async function showDeletedOrders(){try{const orders=(await api("/api/admin/orders/deleted")).orders;modal("ประวัติออเดอร์ที่ลบ",`<div class="deleted-order-list">${orders.length?orders.map(order=>`<article class="deleted-order-card"><div><b>${esc(order.id)}</b><span>${esc(order.customer_name)} · ${money.format(order.total)}</span><small>ลบโดย <strong>${esc(order.deleted_by_name||order.deleted_by||"ไม่ทราบ")}</strong> · ${date(order.deleted_at)}</small><small>เหตุผล: ${esc(order.delete_reason||"—")}</small></div><div><span class="badge">${esc(labels[order.status]||order.status)}</span>${order.stock_returned_at?'<b class="green">✓ คืนสต็อกแล้ว</b>':`<button class="button small" data-restore-order-stock="${esc(order.id)}">คืนสต็อกเดิม</button>`}</div></article>`).join(""):'<p class="muted">ยังไม่มีออเดอร์ที่ถูกลบ</p>'}</div><p class="notice">รายการที่ลบจะไม่แสดงในหน้าทำงาน รายงาน การเงิน หรือค่าคอม แต่เก็บ Audit สำหรับ OWNER</p>`)}catch(error){toast(errorText(error))}}
async function restoreDeletedStock(id){if(!confirm(`คืนสต็อกจากออเดอร์ ${id}?\nใช้สำหรับออเดอร์ที่ลบก่อนติดตั้งระบบคืนสต็อกอัตโนมัติ`))return;try{const result=await api(`/api/admin/orders/${encodeURIComponent(id)}/restore-stock`,{method:"POST",body:"{}"});toast(`คืนสต็อกแล้ว ${Number(result.returnedQuantity||0)} หน่วย`);await Promise.all([loadProducts(),loadDashboard(),showDeletedOrders()])}catch(error){toast(error.message==="stock_already_returned"?"ออเดอร์นี้คืนสต็อกแล้ว":errorText(error))}}
async function transition(id,next,extra={}){if(next==="CANCELLED"&&!confirm("ยืนยันยกเลิกออเดอร์และคืนสต็อก?"))return;try{await api(`/api/admin/orders/${encodeURIComponent(id)}/transition`,{method:"POST",body:JSON.stringify({status:next,...extra})});toast("อัปเดตสถานะเรียบร้อย");closeModal();await Promise.all([loadOrders(),loadDashboard()])}catch(error){toast(errorText(error))}}
async function rollbackPacking(id,current,paymentMethod){const reason=prompt("ระบุเหตุผลที่ย้อนสถานะแพ็ก");if(!reason?.trim())return;const target=current==="PACKED"?"PACKING":paymentMethod==="COD"?"ACCEPTED":"PAID";await transition(id,target,{reason:reason.trim()})}
async function confirmCod(id){if(!confirm("ยืนยันว่าได้รับยอดเงิน COD จากบริษัทขนส่งแล้ว?"))return;try{await api(`/api/admin/orders/${encodeURIComponent(id)}/cod-received`,{method:"POST",body:"{}"});toast("ยืนยันยอด COD แล้ว สามารถปิดออเดอร์ได้");await Promise.all([loadOrders(),loadDashboard()])}catch(error){toast(errorText(error))}}
function shippingModal(id){modal("บันทึกการจัดส่ง",`<form id="shippingForm" class="form"><label>บริษัทขนส่ง<input id="trackingCompany" class="field" list="carrierList" required placeholder="เลือกหรือพิมพ์บริษัทขนส่ง"><datalist id="carrierList"><option value="Thailand Post"><option value="Kerry Express"><option value="Flash Express"><option value="J&T Express"><option value="SPX Express"><option value="Ninja Van"></datalist></label><label>เลขพัสดุ<input id="trackingNumber" class="field" required autocomplete="off" placeholder="กรอกเลขพัสดุ"></label><p class="notice">ลูกค้าจะเห็นปุ่มติดตาม คัดลอก และแชร์เลขพัสดุทันที</p><button class="button" type="submit">ยืนยันจัดส่ง</button></form>`);$("#shippingForm").onsubmit=event=>{event.preventDefault();transition(id,"SHIPPED",{trackingCompany:$("#trackingCompany").value,trackingNumber:$("#trackingNumber").value})}}

async function loadProducts(){try{state.products=(await api("/api/admin/products")).products;const categories=[...new Set(state.products.map(product=>product.category).filter(Boolean))].sort((a,b)=>a.localeCompare(b,"th")),posCategory=$("#posCategory"),productCategory=$("#productCategoryFilter");if(posCategory){const current=posCategory.value;posCategory.innerHTML='<option value="">ทุกหมวดหมู่</option>'+categories.map(category=>`<option value="${esc(category)}">${esc(category)}</option>`).join("");posCategory.value=categories.includes(current)?current:""}if(productCategory){const current=productCategory.value;productCategory.innerHTML='<option value="">ทุกหมวดหมู่</option>'+categories.map(category=>`<option value="${esc(category)}">${esc(category)}</option>`).join("");productCategory.value=categories.includes(current)?current:""}renderProductTable();renderProductPicker();renderPosProducts()}catch(error){toast(errorText(error))}}
function tiers(product){const entries=Object.entries(product.prices||{}).map(([size,price])=>[Number(size),Number(price)]).filter(([size,price])=>size>0&&Number.isFinite(price)).sort((a,b)=>a[0]-b[0]);return entries.length?entries:[[1,Number(product.price||0)]]}
function posSizeLabel(product,size){const value=Number(size),display=Number.isInteger(value)?String(value):String(value).replace(/0+$/,"").replace(/\.$/,"");return String(product.unit||"").toLowerCase().replace(".","")==="g"?`${display}G`:`${display} ${product.unit}`}
function applyPosSalesAgent(agent){state.salesAgent=agent||null;const input=$("#posAgent"),status=$("#posAgentStatus");if(!input||!status)return;if(agent){input.value=agent.code;input.readOnly=true;input.setAttribute("aria-readonly","true");status.classList.remove("hidden");status.innerHTML=`<b>เซลล์ประจำบิล: ${esc(agent.name)}</b><span>รหัส ${esc(agent.code)} · ค่าคอม ${Number(agent.commission_rate)}% · ระบบผูกให้อัตโนมัติ</span>`}else{input.readOnly=false;input.removeAttribute("aria-readonly");status.classList.add("hidden");status.innerHTML=""}}
function renderPosProducts(){const root=$("#posProducts");if(!root)return;const term=$("#posSearch").value.trim().toLowerCase(),category=$("#posCategory")?.value||"",rows=state.products.filter(product=>product.status==="ACTIVE"&&(!category||product.category===category)&&(!term||product.name.toLowerCase().includes(term)||product.category.toLowerCase().includes(term))).slice(0,100);root.innerHTML=rows.length?rows.map(product=>{const options=tiers(product),availableOptions=options.filter(([size])=>Number(size)<=Number(product.stock||0)),firstSize=Number(availableOptions[0]?.[0]||1),maxQty=Math.max(0,Math.floor(Number(product.stock||0)/firstSize));return`<article class="pos-product-card"><div class="pos-product-image">${product.images?.[0]?`<img src="${esc(product.images[0])}" alt="${esc(product.name)}">`:`<img src="/assets/jigz-planet.png" alt="">`}</div><div class="pos-product-body"><span class="tag">${esc(product.category)}</span><h3>${esc(product.name)}</h3><span class="pos-stock ${Number(product.stock)>0?"ready":"empty"}">${Number(product.stock)>0?`คงเหลือ ${Number(product.stock)} ${esc(product.unit)}`:"รอรีสต็อก"}</span><div class="pos-rate-list">${options.slice(0,7).map(([size])=>`<span>${esc(posSizeLabel(product,size))}</span>`).join("")}</div><label>เลือกขนาด / เรทราคา<select id="tier-${esc(product.id)}" class="field" data-pos-tier="${esc(product.id)}">${options.map(([size,price])=>`<option value="${size}" ${Number(size)<=Number(product.stock||0)?"":"disabled"}>${esc(posSizeLabel(product,size))} · ${money.format(price)}${Number(size)<=Number(product.stock||0)?"":" · สต็อกไม่พอ"}</option>`).join("")}</select></label><div class="pos-add-controls"><label>จำนวนแพ็ก<input id="pos-add-qty-${esc(product.id)}" class="field pos-number-input" data-pos-product-qty="${esc(product.id)}" type="number" inputmode="numeric" min="1" max="${maxQty}" step="1" value="1" ${availableOptions.length?"":"disabled"}></label><button class="button" data-pos-add="${esc(product.id)}" ${availableOptions.length?"":"disabled"}>＋ เพิ่ม</button></div></div></article>`}).join(""):'<div class="empty">ไม่พบสินค้าที่ค้นหา</div>'}
function posReserved(productId,exceptKey=""){return state.posCart.filter(line=>line.productId===productId&&line.key!==exceptKey).reduce((sum,line)=>sum+Number(line.packSize)*Number(line.qty),0)}
function posMaxQty(line){const product=state.products.find(item=>item.id===line.productId),available=Math.max(0,Number(product?.stock||0)-posReserved(line.productId,line.key));return Math.max(0,Math.floor((available+1e-9)/Number(line.packSize)))}
function canIncreasePos(line){return Number(line.qty)<posMaxQty(line)}
function syncPosProductQty(id){const product=state.products.find(item=>item.id===id),tier=document.getElementById(`tier-${id}`),input=document.getElementById(`pos-add-qty-${id}`),button=document.querySelector(`[data-pos-add="${CSS.escape(id)}"]`);if(!product||!tier||!input)return;const packSize=Number(tier.value||1),remaining=Math.max(0,Number(product.stock||0)-posReserved(id)),maxQty=Math.max(0,Math.floor((remaining+1e-9)/packSize));input.max=String(maxQty);input.disabled=maxQty<1;if(maxQty<1)input.value="0";else input.value=String(Math.min(maxQty,Math.max(1,Math.floor(Number(input.value)||1))));if(button)button.disabled=maxQty<1}
function setPosQuantity(key,value){const line=state.posCart.find(item=>item.key===key);if(!line)return;const requested=Math.floor(Number(value)),maximum=posMaxQty(line);if(Number.isFinite(requested)&&requested<=0)state.posCart=state.posCart.filter(item=>item!==line);else if(maximum<1){state.posCart=state.posCart.filter(item=>item!==line);toast("สต็อกสินค้านี้ไม่เพียงพอ")}else if(!Number.isFinite(requested)){renderPosCart();return}else{line.qty=Math.min(requested,maximum);if(requested>maximum)toast(`ใส่ได้สูงสุด ${maximum} แพ็กตามสต็อกคงเหลือ`)}renderPosCart();syncPosProductQty(line.productId)}
function setPosPrice(key,value){const line=state.posCart.find(item=>item.key===key),salePrice=Number(value);if(!line)return;if(!Number.isFinite(salePrice)||salePrice<=0||salePrice>1e8){toast("ราคาขายต้องมากกว่า 0 บาท");renderPosCart();return}line.salePrice=Math.round(salePrice*100)/100;renderPosCart()}
function togglePosCart(force){const open=typeof force==="boolean"?force:!document.body.classList.contains("pos-cart-open"),toggle=$("#posCartToggle");document.body.classList.toggle("pos-cart-open",open);if(toggle)toggle.setAttribute("aria-expanded",String(open));if(open)setTimeout(()=>$("#posCartPanel")?.querySelector("input,select,textarea,button")?.focus({preventScroll:true}),180)}
function addPos(id){const product=state.products.find(item=>item.id===id),packSize=Number(document.getElementById(`tier-${id}`)?.value||1),input=document.getElementById(`pos-add-qty-${id}`),addQty=Math.max(1,Math.floor(Number(input?.value)||1)),key=`${id}|${packSize}`,line=state.posCart.find(item=>item.key===key),requested=posReserved(id)+packSize*addQty,listedPrice=Number(product?.prices?.[String(packSize)]??product?.price??0);if(!product||requested>Number(product.stock))return toast("เพิ่มไม่ได้ จำนวนสินค้าไม่เพียงพอ");if(line)line.qty+=addQty;else state.posCart.push({key,productId:id,packSize,qty:addQty,salePrice:listedPrice});renderPosCart();syncPosProductQty(id)}
function renderPosCart(){const root=$("#posCart");let total=0;root.innerHTML=state.posCart.length?state.posCart.map(line=>{const product=state.products.find(item=>item.id===line.productId),listedPrice=Number(product?.prices?.[String(line.packSize)]??product?.price??0),price=Number(line.salePrice??listedPrice),maximum=posMaxQty(line),overridden=Math.abs(price-listedPrice)>.009;total+=price*line.qty;return`<div class="cart-line pos-cart-line ${overridden?"pos-price-overridden":""}"><div><b>${esc(product?.name)}</b><small>${esc(posSizeLabel(product||{unit:""},line.packSize))} × ${line.qty} แพ็ก${overridden?" · ราคาพิเศษเฉพาะบิล":""}</small></div><b>${money.format(price*line.qty)}</b><div class="pos-qty-control"><button type="button" data-pos-qty="-1" data-pos-key="${esc(line.key)}" aria-label="ลดจำนวน">−</button><input class="pos-qty-input" data-pos-qty-input data-pos-key="${esc(line.key)}" type="number" inputmode="numeric" min="1" max="${maximum}" step="1" value="${line.qty}" aria-label="จำนวนแพ็ก ${esc(product?.name)}"><button type="button" data-pos-qty="1" data-pos-key="${esc(line.key)}" aria-label="เพิ่มจำนวน" ${canIncreasePos(line)?"":"disabled"}>+</button></div><label class="pos-price-edit"><span>ราคาขาย/แพ็ก <small>เฉพาะบิลนี้ · ราคาปกติ ${money.format(listedPrice)}</small></span><input class="pos-price-input" data-pos-price-input data-pos-key="${esc(line.key)}" type="number" inputmode="decimal" min="0.01" max="100000000" step="0.01" value="${price}" aria-label="ราคาขายต่อแพ็ก ${esc(product?.name)}"></label></div>`}).join(""):"<p class=\"muted pos-cart-empty\">เลือกสินค้าแล้วกำหนดจำนวน หรือเพิ่ม/ลดด้วยปุ่ม − และ +</p>";state.posSubtotal=total;updatePosTotals()}
