$("#posForm").onsubmit=async event=>{event.preventDefault();if(!state.posCart.length)return toast("ยังไม่มีสินค้า");const totals=posTotals(),paymentMethod=$("#posPayment").value,codAmount=paymentMethod==="COD"?Number($("#posCodAmount").value):null;if(paymentMethod==="COD"&&(!Number.isFinite(codAmount)||codAmount+0.009<totals.total))return toast("ยอดเก็บปลายทางต้องไม่น้อยกว่ายอดสุทธิ");try{const result=await api("/api/admin/orders",{method:"POST",body:JSON.stringify({customerName:$("#posName").value,phone:$("#posPhone").value,address:$("#posAddress").value,paymentMethod,discount:totals.discount,shippingFee:totals.shipping,codAmount,agentCode:$("#posAgent").value,items:state.posCart.map(({productId,packSize,qty,salePrice})=>({productId,packSize,qty,salePrice}))})});if(result.approvalRequired){state.posCart=[];renderPosCart();event.target.reset();$("#posShipping").value=state.settings?.shipping_fee||"0";$("#posShipping").dataset.edited="";$("#posCodAmount").dataset.edited="";updatePosTotals();applyPosSalesAgent(state.salesAgent);modal("ส่งขออนุมัติราคาพิเศษแล้ว",`<p class="notice">บิลนี้มีส่วนลด ${Number(result.quote.discountPercent).toFixed(2)}% และกำไร ${Number(result.quote.marginPercent).toFixed(2)}% เกินเงื่อนไขที่เซลล์อนุมัติเองได้</p><p>รหัสคำขอ <b>${esc(result.approvalId)}</b></p><p>ระบบยังไม่ตัดสต๊อกและยังไม่สร้างบิล จนกว่า OWNER หลักจะอนุมัติ</p>`);return}const order=result.order;state.posCart=[];event.target.reset();$("#posShipping").value=state.settings?.shipping_fee||"0";$("#posShipping").dataset.edited="";$("#posCodAmount").dataset.edited="";renderPosCart();applyPosSalesAgent(state.salesAgent);modal("ขายสำเร็จ",`<div class="receipt"><h2>JIGᶻ AGENT</h2><p>เลขที่ ${esc(order.id)} · ${date(order.created_at)}</p><p>ลูกค้า ${esc(order.customer_name)}</p>${order.agent_code?`<p>เซลล์ ${esc(order.agent_code)}${state.salesAgent?` · ${esc(state.salesAgent.name)}`:""}</p>`:""}<table><thead><tr><th>สินค้า</th><th>จำนวน</th><th>ราคา/แพ็ก</th><th>รวม</th></tr></thead><tbody>${order.items.map(item=>`<tr><td>${esc(item.product_name)}</td><td>${item.quantity} ${esc(item.unit)}</td><td>${money.format(Number(item.unit_price)*Number(item.pack_size))}</td><td>${money.format(item.line_total)}</td></tr>`).join("")}</tbody></table><div class="receipt-totals"><p><span>ยอดสินค้า</span><b>${money.format(order.subtotal)}</b></p><p><span>ส่วนลด</span><b>−${money.format(order.discount)}</b></p><p><span>ค่าจัดส่ง</span><b>${money.format(order.shipping_fee)}</b></p><h2><span>ยอดสุทธิ</span><b>${money.format(order.total)}</b></h2>${order.payment_method==="COD"?`<h2 class="cod-receipt-total"><span>ยอดเก็บปลายทาง</span><b>${money.format(order.cod_amount)}</b></h2>`:""}</div><p>ราคาที่แก้ใน POS ใช้เฉพาะบิลนี้เท่านั้น</p><p>ขอบคุณที่ไว้วางใจ JIGᶻ AGENT</p></div><p><button class="button" onclick="window.print()">พิมพ์ / บันทึกบิล</button></p>`);await loadProducts();if(!document.body.classList.contains("sales-mode"))await loadDashboard();else await loadMySales()}catch(error){toast(errorText(error))}};
