let adminAccessPoll=null;
async function refreshAdminAccessGate(){try{const result=await api("/api/admin/access-request");if(result.authorized){clearInterval(adminAccessPoll);location.reload();return}$("#gateDevice").textContent=`รหัสอุปกรณ์: ${result.user.display_name} · ${result.user.id}`;$("#gateDevice").classList.remove("hidden");const pending=result.request?.status==="PENDING",rejected=result.request?.status==="REJECTED";$("#gateText").textContent=pending?"ส่งคำขอแล้ว กำลังรอ OWNER อนุมัติอุปกรณ์นี้":rejected?"คำขอก่อนหน้าถูกปฏิเสธ คุณสามารถส่งคำขอใหม่ได้":"อุปกรณ์นี้ยังไม่มีสิทธิ์เข้าหลังบ้าน";$("#gateRequest").classList.toggle("hidden",pending);$("#gateRequest").textContent=rejected?"ส่งคำขอใหม่":"ส่งคำขอสิทธิ์แอดมิน";$("#gateRefresh").classList.toggle("hidden",!pending);$("#gateBack").classList.remove("hidden");$(".loader").classList.add("hidden");if(pending&&!adminAccessPoll)adminAccessPoll=setInterval(refreshAdminAccessGate,5000)}catch{$("#gateText").textContent="ตรวจสอบสิทธิ์อุปกรณ์ไม่สำเร็จ กรุณาลองใหม่";$("#gateBack").classList.remove("hidden");$(".loader").classList.add("hidden")}}
$("#gateRequest").onclick=async()=>{try{$("#gateRequest").disabled=true;await api("/api/admin/access-request",{method:"POST",body:"{}"});await refreshAdminAccessGate()}catch(error){$("#gateText").textContent=errorText(error)}finally{$("#gateRequest").disabled=false}};
$("#gateRefresh").onclick=refreshAdminAccessGate;
setTimeout(()=>{if(!$("#gate").classList.contains("hidden")&&!$(".loader").classList.contains("hidden")){$("#gateText").textContent="การตรวจสอบใช้เวลานานกว่าปกติ กรุณากดตรวจสอบอีกครั้ง";$("#gateRefresh").classList.remove("hidden");$("#gateBack").classList.remove("hidden");$(".loader").classList.add("hidden")}},9000);
api("/api/admin/session").then(async result=>{state.user=result.user;applyPosSalesAgent(result.salesAgent);const salesMode=result.effectiveRole==="SALES";if(result.salesAgent)$("#mySalesNav").classList.remove("hidden");$("#adminName").textContent=result.user.display_name;$("#adminRole").textContent=salesMode?`Sales · ${result.salesAgent.code}`:result.user.role==="OWNER"?result.user.is_primary_owner?"OWNER หลัก · ผู้ยืนยันระบบ":"OWNER รอง · ผู้ดูแลระบบ":"Administrator";if(result.user.role==="OWNER")document.querySelectorAll(".owner-only").forEach(node=>node.classList.remove("hidden"));if(salesMode){document.body.classList.add("sales-mode");document.querySelectorAll("#nav [data-view]").forEach(node=>node.classList.toggle("hidden",!["pos","my-sales"].includes(node.dataset.view)));$("#globalSearch").classList.add("hidden")}$("#gate").classList.add("hidden");$("#app").classList.remove("hidden");if(salesMode){await Promise.all([loadProducts(),loadMySales(),checkPush()]);showView("pos")}else{await Promise.all([loadDashboard(),loadProducts(),loadSettings(),loadWalletRequests(),checkPush()]);startOrderMonitor()}}).catch(error=>{if(error.message==="device_not_authorized")refreshAdminAccessGate();else{$("#gateText").textContent="เปิดระบบหลังบ้านไม่สำเร็จ";$("#gateBack").classList.remove("hidden");$(".loader").classList.add("hidden")}});
